import java.time.*;import java.util.*;interface Seat{double getPrice();String getId();}class Regular implements Seat{String id;Regular(String i){id=i;}public double getPrice(){return 150;}public String getId(){return id;}}class Premium implements Seat{String id;Premium(String i){id=i;}public double getPrice(){return 250;}public String getId(){return id;}}class Recliner implements Seat{String id;Recliner(String i){id=i;}public double getPrice(){return 400;}public String getId(){return id;}}class Customer{String name;Customer(String n){name=n;}}class Show{LocalDateTime starts;Set<String> booked=new HashSet<>();Show(LocalDateTime s){starts=s;}void reserve(Seat s){if(!booked.add(s.getId()))throw new IllegalStateException();}void release(Seat s){booked.remove(s.getId());}}class Booking{Customer customer;Show show;List<Seat> seats;boolean active=true;Booking(Customer c,Show sh,List<Seat> ss){if(ss.size()<1||ss.size()>6)throw new IllegalArgumentException();for(Seat s:ss)sh.reserve(s);customer=c;show=sh;seats=new ArrayList<>(ss);}double total(){double x=0;for(Seat s:seats)x+=s.getPrice();return x;}void cancel(LocalDateTime now){if(!now.isBefore(show.starts))throw new IllegalStateException();if(active){for(Seat s:seats)show.release(s);active=false;}}}public class Main{public static void main(String[]a){}}